import { assertDeliverable } from './recipients.js';
import { transport } from './transport.js';

export class InvalidRecipient extends Error {}

export interface Message {
  to: string;
  subject: string;
  text: string;
}

export async function send(message: Message): Promise<void> {
  try {
    assertDeliverable(message.to);
  } catch (err) {
    throw new InvalidRecipient(err instanceof Error ? err.message : String(err));
  }
  await transport.deliver({
    to: message.to,
    subject: message.subject,
    body: message.text,
  });
}
